'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "joinaggregate": [
        {
          "op": "mean",
          "field": "Faturamento Total",
          "as": "media"
        },
        {
          "op": "max",
          "field": "Faturamento Total",
          "as": "maximo"
        }
      ]
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "area",
        "interpolate": "monotone",
        "color": {
          "gradient": "linear",
          "x1": 1,
          "y1": 1,
          "x2": 1,
          "y2": 0,
          "stops": [
            {
              "offset": 0,
              "color": "rgba(0,203,169,0.02)"
            },
            {
              "offset": 1,
              "color": "rgba(0,203,169,0.38)"
            }
          ]
        }
      },
      "encoding": {
        "x": {
          "field": "Mês Ano",
          "type": "ordinal",
          "sort": {
            "field": "AnoMes",
            "op": "min",
            "order": "ascending"
          },
          "axis": {
            "title": null,
            "labelAngle": 0,
            "labelOverlap": "parity",
            "labelFontSize": 9
          }
        },
        "y": {
          "field": "Faturamento Total",
          "type": "quantitative",
          "axis": {
            "title": null,
            "grid": true,
            "gridColor": "#EEF2F6",
            "gridDash": [
              3,
              3
            ],
            "tickCount": 4,
            "formatType": "pbiFormat",
            "format": "R$ #,0"
          },
          "scale": {
            "zero": true
          }
        }
      }
    },
    {
      "mark": {
        "type": "line",
        "interpolate": "monotone",
        "color": "#00CBA9",
        "strokeWidth": 2.6
      },
      "encoding": {
        "x": {
          "field": "Mês Ano",
          "type": "ordinal",
          "sort": {
            "field": "AnoMes",
            "op": "min",
            "order": "ascending"
          },
          "axis": {
            "title": null,
            "labelAngle": 0,
            "labelOverlap": "parity",
            "labelFontSize": 9
          }
        },
        "y": {
          "field": "Faturamento Total",
          "type": "quantitative"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.AnoMes % 100 == 1"
        }
      ],
      "mark": {
        "type": "rule",
        "color": "#CBD5E1",
        "strokeWidth": 1
      },
      "encoding": {
        "x": {
          "field": "Mês Ano",
          "type": "ordinal",
          "sort": {
            "field": "AnoMes",
            "op": "min",
            "order": "ascending"
          },
          "axis": {
            "title": null,
            "labelAngle": 0,
            "labelOverlap": "parity",
            "labelFontSize": 9
          }
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.AnoMes % 100 == 1"
        },
        {
          "calculate": "toString(floor(datum.AnoMes / 100))",
          "as": "anoTxt"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "top",
        "dx": 5,
        "y": 2,
        "fontSize": 11,
        "fontWeight": 700,
        "color": "#94A3B8"
      },
      "encoding": {
        "x": {
          "field": "Mês Ano",
          "type": "ordinal",
          "sort": {
            "field": "AnoMes",
            "op": "min",
            "order": "ascending"
          },
          "axis": {
            "title": null,
            "labelAngle": 0,
            "labelOverlap": "parity",
            "labelFontSize": 9
          }
        },
        "text": {
          "field": "anoTxt"
        }
      }
    },
    {
      "mark": {
        "type": "rule",
        "color": "#2C3E50",
        "strokeDash": [
          4,
          4
        ],
        "strokeWidth": 1,
        "opacity": 0.55
      },
      "encoding": {
        "y": {
          "field": "media",
          "aggregate": "min",
          "type": "quantitative"
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "bottom",
        "dy": -4,
        "fontSize": 10,
        "color": "#2C3E50",
        "opacity": 0.75,
        "x": {
          "expr": "width"
        }
      },
      "encoding": {
        "y": {
          "field": "media",
          "aggregate": "min",
          "type": "quantitative"
        },
        "text": {
          "field": "media",
          "aggregate": "min",
          "type": "quantitative",
          "formatType": "pbiFormat",
          "format": "R$ #,0"
        }
      }
    },
    {
      "mark": {
        "type": "rule",
        "color": "#94A3B8",
        "strokeWidth": 1
      },
      "encoding": {
        "x": {
          "field": "Mês Ano",
          "type": "ordinal",
          "sort": {
            "field": "AnoMes",
            "op": "min",
            "order": "ascending"
          },
          "axis": {
            "title": null,
            "labelAngle": 0,
            "labelOverlap": "parity",
            "labelFontSize": 9
          }
        },
        "opacity": {
          "condition": {
            "param": "hover",
            "empty": false,
            "value": 0.7
          },
          "value": 0
        }
      }
    },
    {
      "mark": {
        "type": "point",
        "filled": true,
        "size": 80,
        "color": "#00CBA9",
        "stroke": "white",
        "strokeWidth": 2
      },
      "encoding": {
        "x": {
          "field": "Mês Ano",
          "type": "ordinal",
          "sort": {
            "field": "AnoMes",
            "op": "min",
            "order": "ascending"
          },
          "axis": {
            "title": null,
            "labelAngle": 0,
            "labelOverlap": "parity",
            "labelFontSize": 9
          }
        },
        "y": {
          "field": "Faturamento Total",
          "type": "quantitative"
        },
        "opacity": {
          "condition": {
            "param": "hover",
            "empty": false,
            "value": 1
          },
          "value": 0
        }
      }
    },
    {
      "params": [
        {
          "name": "hover",
          "select": {
            "type": "point",
            "encodings": [
              "x"
            ],
            "on": "mouseover",
            "clear": "mouseout"
          }
        }
      ],
      "mark": {
        "type": "bar",
        "opacity": 0,
        "width": {
          "band": 1
        },
        "cursor": "pointer",
        "tooltip": true
      },
      "encoding": {
        "x": {
          "field": "Mês Ano",
          "type": "ordinal",
          "sort": {
            "field": "AnoMes",
            "op": "min",
            "order": "ascending"
          },
          "axis": {
            "title": null,
            "labelAngle": 0,
            "labelOverlap": "parity",
            "labelFontSize": 9
          }
        },
        "y": {
          "field": "maximo",
          "type": "quantitative"
        },
        "y2": {
          "datum": 0
        }
      }
    }
  ]
}'

'{
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "padding": {
    "left": 4,
    "right": 8,
    "top": 8,
    "bottom": 4
  },
  "background": null,
  "font": "Inter, Segoe UI, Arial, sans-serif",
  "view": {
    "stroke": "transparent"
  },
  "axis": {
    "domain": false,
    "ticks": false,
    "grid": false,
    "labelColor": "#64748B",
    "labelFontSize": 10,
    "labelFont": "Inter, Segoe UI, Arial, sans-serif",
    "titleColor": "#64748B",
    "titleFontSize": 10,
    "titleFontWeight": "normal",
    "labelPadding": 6
  },
  "legend": {
    "labelColor": "#64748B",
    "labelFontSize": 10,
    "labelFont": "Inter, Segoe UI, Arial, sans-serif",
    "titleColor": "#64748B",
    "symbolType": "circle",
    "symbolSize": 80
  },
  "text": {
    "font": "Inter, Segoe UI, Arial, sans-serif",
    "color": "#2C3E50"
  },
  "line": {
    "strokeCap": "round"
  },
  "range": {
    "category": [
      "#00CBA9",
      "#2C3E50",
      "#33D6BB",
      "#5D6D7E",
      "#80E5D4",
      "#AAB7C4"
    ]
  }
}'
